INSERT INTO `tblcustomnotes` (`cn_id`, `cn_title`, `cn_type`, `cn_notes`, `cn_position`, `en_userId`, `en_dateadded`) VALUES
(2, 'Proposal before Template Note', 'proposal', 'Dear Sir <br><br>We gratefully acknowledge the opportunity given us, to discuss the possibility of providing our services for developing a Dynamic CMS based Website for your prestige Organization. We give hereunder the basic understandings about the requirements, Scope, and Terms & Conditions', 'top', 1, '2017-10-29 09:57:08'),
(4, 'Invoice General Terms', 'invoice', '<p>Please make Payment through Cross Check or Bank Transfer.</p>\r\n<p><strong>Bank:</strong><span> </span>Emirates NBD<br><strong>Title:</strong><span> </span>Wisdom Information Technology Solutions LLC<br><strong>Ac #:</strong> 101-22900837-01 (AE740260001012290083701)</p>', 'bottom', 22, '2017-11-23 15:28:37'),
(5, 'Design Terms', 'proposal', '<p><strong>Terms & Conditions:</strong></p>\r\n<p><strong>Turn Around Time:</strong><span> </span>3-5 Days</p>\r\n<p><strong>Payment Terms:</strong><span> </span>50?vance and 50% on Completion</p>\r\n<p><strong>Delivery Format:</strong><span> </span>JPG, Illustrator (ai) and Png</p>', '', 1, '2017-11-01 17:27:53'),
(6, 'Web Design Terms', 'proposal', '<p><strong>Terms & Conditions:</strong></p>\r\n<ul xss=\"removed\">\r\n<li>6-month free maintenance (Troubleshooting, Bug removal and free Email Support)</li>\r\n<li>Payment Terms: 50?vance, 50% on completion.</li>\r\n<li>Data Entry and Site maintenance shall be the responsibility of the client. However, Wisdom can provide the same on additional charges.</li>\r\n<li>Time Period: 4 weeks after Design approval.</li>\r\n<li>Please make Payment through Cross Check or Bank Transfer.</li>\r\n<li>VAT is not included in above prices.</li>\r\n</ul>', '', 1, '2018-01-30 12:46:35'),
(7, 'Terms and Conditions.', 'proposal', '<div class=\"page\" title=\"Page 1\">\r\n<div class=\"section\">\r\n<div class=\"layoutArea\">\r\n<div class=\"column\">\r\n<p><span>Terms and Conditions </span></p>\r\n</div>\r\n</div>\r\n<div class=\"layoutArea\">\r\n<div class=\"column\">\r\n<p><span>1. All prices in UAE Dirham.<br> 3. 50% in advance with LPO and balance 50% on delivery 4. Offer validity : one week </span></p>\r\n</div>\r\n</div>\r\n<div class=\"layoutArea\">\r\n<div class=\"column\">\r\n<p><span>We hope the prices meet with you approval and we look forward to hear from you soon. If you need further clarifications feel free to contact us. </span></p>\r\n<p><span>Please make Payment through Cross Check or Bank Transfer. </span><span>Bank: </span><span>Emirates NBD<br> </span><span>Title: </span><span>Wisdom Information Technology Solutions LLC<br> </span><span>Ac #: </span><span>101-22900837-01 (AE740260001012290083701) </span></p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>', '', 21, '2018-04-07 13:14:48'),
(8, 'Benchmark Pest Control Services LLC', 'proposal', 'SSL &amp; web designing<br>Send Proposal to Mr. Lazif Sifram<br><a href=\"mailto:benchdxb@eim.ae\">benchdxb@eim.ae</a><br>042355937<br>065387197<br>Called on Date: 26-Apr-2018', 'top', 30, '2018-04-26 21:01:45'),
(9, 'Akkad Pest control', 'proposal', 'SSL &amp; web designing<br>Send proposal to Mr. Omar<br><a href=\"mailto:info@pestcontrol.ae\">info@pestcontrol.ae</a><br>043966211 0504001344', 'top', 30, '2018-04-26 21:04:04'),
(10, 'mxDubai Motorcycle Rental', 'proposal', 'Web designing<br>Sent proposal to Mr sohail<br><a href=\"mailto:info@mxdubai.com\">info@mxdubai.com</a><br>055 262 2707<br><br>Called previously, today (26-Apr-2018) a followup call was made<br>No Answer Call Back on Saturday', 'top', 30, '2018-04-26 21:08:58'),
(11, 'Sumar Auto Spare Parts Trd. (L.L.C)', 'proposal', 'Web designing<br>Sent proposal to Mr Salem<br><a href=\"mailto:Info@sumarauto.com\">Info@sumarauto.com</a>  <a href=\"mailto:accounts3@sumarauto.com\">accounts3@sumarauto.com </a><br>97142279874  97142279873<br>This customer was called in previous days, today (26-Apr-2018) a followup call was made.<br>No Answer Call Back on Saturday', 'top', 30, '2018-04-26 21:11:31');
