INSERT INTO `tblitems` (`id`, `description`, `long_description`, `rate`, `tax`, `tax2`, `unit`, `group_id`, `rate_currency_3`, `item_type`) VALUES
(11, 'Custom Web Development Service', 'Description Goes here', '0.00', NULL, NULL, NULL, 1, NULL, 'other'),
(22, 'Web Hosting 10000', '<ul>\r\n<li>Web Hosting 10,000 MB</li>\r\n<li>Bandwidth: 100,000 MB Per month</li>\r\n<li>Languages Support: PHP, Java</li>\r\n<li>Database: MYSQL (Unlimited Databases)</li>\r\n<li>Number of Emails: Unlimited</li>\r\n</ul>', '165.00', NULL, NULL, NULL, 4, NULL, 'other'),
(2, 'Logo Design', '<ul>\r\n<li>Professional Logo Designing</li>\r\n<li><span style=\"font-size: 10pt;\">High resolution file format</span></li>\r\n<li><span style=\"font-size: 10pt;\">7 Unique Logo Design Concepts to Choose from</span></li>\r\n<li><span style=\"font-size: 10pt;\">7 Logo Designers will work on the Project</span></li>\r\n<li><span style=\"font-size: 10pt;\">Unlimited Revisions till you 100% Satisfied</span></li>\r\n<li><span style=\"font-size: 10pt;\">No Clipart Used</span></li>\r\n<li><span style=\"font-size: 10pt;\">2 Redraws</span></li>\r\n</ul>\r\n<p>- Fully Copyright</p>', '2000.00', NULL, NULL, NULL, 1, NULL, 'other'),
(3, 'Domain Registration / Renewal ', '<p>www.DomainName.com</p>', '100.00', NULL, NULL, '', 12, '0.00', 'domain'),
(5, 'Email Hosting', '<p>Unlimited Emails Hosting Each Email will have 2GB State of the Art Infrastructure Easy to Use Web Mail Integrated with Social Media Anti Virus &amp; SPAM Control</p>', '3600.00', NULL, NULL, NULL, 4, NULL, 'other'),
(7, 'Web Hosting 100', 'Web Hosting 100 MB\r\nLanguages Support: PHP, Java\r\nDatabase: MYSQL (1)\r\nNumber of Emails: 5', '35.00', NULL, NULL, NULL, 4, NULL, 'other'),
(8, 'Google Apps Integration', 'DNS Hosting\r\nDNS Settings for Google Apps Integration', '1000.00', NULL, NULL, NULL, 4, NULL, 'other'),
(9, 'Web Hosting 1000', '<ul>\r\n<li>Web Hosting 1000 MB</li>\r\n<li>Bandwidth: 10,000 MB Per month</li>\r\n<li>Languages Support: PHP, Java</li>\r\n<li>Database: MYSQL (2 Databases)</li>\r\n<li>Number of Emails: 20</li>\r\n</ul>', '75.00', NULL, NULL, NULL, 4, NULL, 'other'),
(21, 'Web Hosting 200', '<ul>\r\n<li>Web Hosting 200 MB</li>\r\n<li>Bandwidth: 2,000 MB Per month</li>\r\n<li>Languages Support: PHP, Java</li>\r\n<li>Database: MYSQL (1 Databases)</li>\r\n<li>Number of Emails: 10</li>\r\n</ul>', '50.00', NULL, NULL, NULL, 4, NULL, 'other'),
(20, 'Web Hosting 500', '<ul>\r\n<li>Web Hosting 500 MB</li>\r\n<li>Bandwidth: 2,000 MB Per month</li>\r\n<li>Languages Support: PHP, Java</li>\r\n<li>Database: MYSQL (1 Databases)</li>\r\n<li>Number of Emails: 15</li>\r\n</ul>', '60.00', NULL, NULL, NULL, 4, NULL, 'other'),
(16, 'Email Marketer Software', '<ul>\r\n<li>High Class Hosted Email Marketing Software</li>\r\n<li>Unlimited Contact Lists, Segmentation</li>\r\n<li>Integration with Website for Newsletter Subscription</li>\r\n<li>Custom Fields</li>\r\n<li>50+ Newsletter Templates -</li>\r\n<li>Bounce Handling and Subscription Management</li>\r\n<li>Surveys and Auto Respondents&nbsp;</li>\r\n<li>Full Campaign Statistics (Open, Clicks, forwards and Bounce)</li>\r\n</ul>', '250.00', NULL, NULL, NULL, 1, NULL, 'other'),
(23, 'Web Designing (CMS)', '<ul>\r\n<li>Graphically Rich web Design With Jquery Banners (English)</li>\r\n<li>Powerful CMS.</li>\r\n<li>Add/Edit/Delete Unlimited Pages and add Unlimited Pictures</li>\r\n<li>Complete Structure will be developed as per the Sitemap provided</li>\r\n<li>Video&nbsp;Enabled&nbsp;</li>\r\n<li>Specialized Media Pages with News Updating Facility</li>\r\n<li>Dynamic Picture Gallery&nbsp;</li>\r\n<li>Social Media Sharing (Facebook Share, Like, Twitter, etc)</li>\r\n<li>SEO Friendly</li>\r\n<li>High class XHTM Standard based development allows future extendibility of features easy</li>\r\n<li>Cross-Browser compatibility</li>\r\n<li>Cross-Device Compatibility</li>\r\n<li>CMS support Adding New features fast and easy</li>\r\n</ul>', '6500.00', NULL, NULL, NULL, 1, NULL, 'other'),
(18, 'Search Engine Optimization (SEO)', '<p>- Free Home Page Search Engine Optimization<br />- Title Tag, Description, Keywords, and Author Tag<br />- Free Search Engine Submission (Google, Yahoo and Bing)<br />- Monthly Packages for On-going and Off-Page SEO are available</p>', '0.00', NULL, NULL, NULL, 1, NULL, 'other'),
(19, 'Web Hosting 5000', '<ul>\r\n<li>Web Hosting 5000 MB</li>\r\n<li>Bandwidth: 50,000 MB Per month</li>\r\n<li>Languages Support: PHP, Java</li>\r\n<li>Database: MYSQL (5 Databases)</li>\r\n<li>Number of Emails: 50</li>\r\n</ul>', '125.00', NULL, NULL, NULL, 4, NULL, 'other'),
(24, 'E-Marketer Newsletter Software', '<p>- Unlimited Lists<br />- Unlimited Segmentation<br />- Email Newsletter Designer<br />- Email Newsletter Templates<br />- Complete Statistics<br />- Surveys<br />- Bounce/Subscription Handling</p>', '3500.00', NULL, NULL, NULL, 3, NULL, 'other'),
(25, 'Email Hosting & SMTP Services', '<ul>\r\n<li>Email Software Hosting</li>\r\n<li>10,000 Email Relays Per month</li>\r\n</ul>', '300.00', NULL, NULL, NULL, 4, NULL, 'other'),
(26, 'CD Catalogue', '<ul>\r\n<li>HTML Website to run Offline without Server</li>\r\n<li>Multi-Category Structure for Products</li>\r\n<li>Auto Run On CD/USB</li>\r\n<li>Flash Splash Screen</li>\r\n</ul>', '5000.00', NULL, NULL, NULL, 1, NULL, 'other'),
(27, 'Stationary Designing', '<ul>\r\n<li><span>Envelop.</span></li>\r\n<li><span>Notepad.</span></li>\r\n<li><span>Letter head.</span></li>\r\n<li><span>Invoice.</span></li>\r\n<li><span>Delivery Order.</span></li>\r\n<li><span>Debit/Credit Vouchers</span></li>\r\n</ul>', '2000.00', NULL, NULL, NULL, 1, NULL, 'other'),
(28, 'E-Commerce Web Development', '<p><strong>- Professionally Designed Store Front with Jquery Banner</strong><strong><br /> <strong>- Mobile Friendly</strong></strong></p>\r\n<p><strong><span style=\"text-decoration: underline;\">Shopping Cart Features:</span></strong></p>\r\n<p><em>Product Catalogue:</em></p>\r\n<ul>\r\n<li>Unlimited Products, Unlimited Categories/Sub Categories Structure</li>\r\n<li>Unlimited Pictures Per Product, Zooming, etc</li>\r\n<li>Separate Meta Tags (Title, Description, Keywords) for each Product</li>\r\n<li>Unlimited Attributes Per Product (Color, Size, etc)</li>\r\n<li>Basic Inventory Management</li>\r\n<li>Integration with eBay, Amazon, Google Shopping and more*</li>\r\n<li>Cross Selling, Up Selling</li>\r\n<li>Products Comparison*</li>\r\n<li>Product Reviews, Tell a Friend and Wish List*</li>\r\n<li>Layered Navigation</li>\r\n<li>Advanced Stock Management*</li>\r\n</ul>\r\n<p><em>Shopping Cart:</em></p>\r\n<ul>\r\n<li>Simple and Easy to Use Order Process</li>\r\n<li>Customer Account or Checkout as guest</li>\r\n<li>One Page Checkout</li>\r\n<li>Gift Messages / Gift Wrapping</li>\r\n</ul>\r\n<p><em>Powerful Shipping Handling:</em></p>\r\n<ul>\r\n<li>Shipping Discounts</li>\r\n<li>Automatic Shipping Calculation by Price or Weight, Zone</li>\r\n<li>Integration with UPS, FedEx</li>\r\n<li>Unlimited Carriers and Destinations</li>\r\n</ul>\r\n<p><em>Payment Gateway:</em></p>\r\n<ul>\r\n<li>Multi Payment Gateway</li>\r\n<li>Integration with Paypal, 2CO, Cash On Delivery</li>\r\n<li>Additional Payment Gateways*</li>\r\n</ul>\r\n<p><em>Order Management &amp; Customer Handling</em></p>\r\n<ul>\r\n<li>Complete Customer Account</li>\r\n<li>Email Notifications to Customers for Change in Order Status</li>\r\n<li>Return Management</li>\r\n<li>Customer Can Track His Order</li>\r\n<li>Complete Statistics</li>\r\n</ul>\r\n<p><em>General Features:</em></p>\r\n<ul>\r\n<li>Multi User Secure Environment</li>\r\n<li>Multi Lingual*</li>\r\n<li>Multi Currency</li>\r\n<li>Multi Store</li>\r\n<li>CRM, ERP Integration*</li>\r\n<li>Simple to use CMS</li>\r\n<li>SEO Friendly (Meta, URLs, Sitemaps)</li>\r\n</ul>\r\n<p>*Extra Cost Items</p>', '8500.00', NULL, NULL, NULL, 1, NULL, 'other'),
(29, 'Custom Web Hosting', '', '0.00', NULL, NULL, NULL, 4, NULL, 'other'),
(30, 'Windows Hosting - 500', '<ul>\r\n<li>Web Hosting 500 MB</li>\r\n<li>Bandwidth: 5,000 MB Per month</li>\r\n<li>Languages Support: ASP, ASP.net, Java</li>\r\n<li>Database: SQL Server, MS Access</li>\r\n<li>Number of Emails: 10</li>\r\n</ul>', '750.00', NULL, NULL, NULL, 4, NULL, 'other'),
(31, 'Deduction', '<p>Description</p>', '1.00', NULL, NULL, NULL, 1, NULL, 'other'),
(32, 'Small Business Starter Website', '<p>- Small Business Modren Style Static Website</p>\r\n<p>- 5 Pages (Home, About Us, Products &amp; Services, Contact Us)</p>\r\n<p>- Jquery Banner (3 Slides Max)</p>\r\n<p>- SEO Friendly</p>\r\n<p>- Mobile Friendly</p>\r\n<p>- Additional Pages Charges: 200 Dhs Per Page</p>', '1500.00', NULL, NULL, NULL, 1, NULL, 'other'),
(33, 'Printing', '', '0.00', NULL, NULL, NULL, 8, NULL, 'other'),
(34, 'Search Engine Optimization (SEO) - Business Starter Package', '<p>- Upload 10 key indexable phrases that you choose to market your business.<br />- Analyze your competition.<br />- Examine the structure and content of your Web site.<br />- Create and upload search-engine friendly meta data.<br />- Provide a comprehensive SEO analysis of your site.<br />- Deliver support to discuss the present and future of your Web site.<br />- Submit your site to up to 100 search engines and directories.<br />- Submission of Press Releases<br />- Submission of Articles to Web 2.0 Properties<br />- Google &amp; Yahoo Site Maps Creation &amp; Submission<br />- Both IN-Page and Off-Page SEO<br />- Competitor Analysis, and Regular steps to increase PR of Site<br />- Monitor traffic using the latest SEO technology.<br />- Site Map Submissions to Google/Yahoo/MSN<br />- Robot.txt Optimization<br />- Social Bookmarking<br />- Content Optimization</p>\r\n<p><strong>Monthly Web Audit</strong><br />- Competition Analysis &amp; Re-Adjustment of On-Page Optimization<br />- Keyword Ranking Report<br />- Link Analysis Report<br />- Web Traffic Report</p>\r\n<p>Min. 1 Year Contract</p>', '3500.00', NULL, NULL, NULL, 1, NULL, 'other'),
(35, 'Career Portal', '<p><strong>Career Portal</strong></p>\r\n<p>&nbsp;</p>\r\n<ol>\r\n<li>Publish Unlimited Jobs</li>\r\n<li>Candidates can browse jobs and Apply for jobs</li>\r\n<li>Candidates can upload CVs</li>\r\n<li>HR Admin with separate user/Pwd</li>\r\n<li>HR Admin can see and download CVs of Candidates who applied for specific job</li>\r\n<li>HR Admin can export all data in Excel</li>\r\n</ol>\r\n<p>&nbsp;</p>', '2500.00', NULL, NULL, NULL, 1, NULL, 'other'),
(36, 'AMC- Annual Maintains Contract.', '<p><span>AMC- Annual Maintains Contract.</span><br /><span>We can Add/ Edit In formations once a Month (12 Time a Year Maximum).</span><br /><span>Any Additions or Changes will be done on request.</span><br /><span>Structure of the Website will not be the Part of Contract.</span><br /><span>Content Include text and Pictures will be change able.</span></p>', '1500.00', NULL, NULL, NULL, 4, NULL, 'other'),
(37, 'Arabic (RTL) Template', '<p><strong>Arabic (RTL) Template:</strong></p>\r\n<ul>\r\n<li>RTL Templateto support Arabic &amp; Other Languages from Right to Left</li>\r\n</ul>', '2500.00', NULL, NULL, NULL, 1, NULL, 'other'),
(38, 'Customer Review System', '<p><strong>Customer Review System:</strong></p>\r\n<ul>\r\n<li>Allows customer to add reviews to product</li>\r\n<li>Admin can moderate customer comments</li>\r\n<li>Benefited for Better Search Engine optimization by adding user generated contents</li>\r\n</ul>', '550.00', NULL, NULL, NULL, 9, NULL, 'other'),
(39, 'Youtube API Integration', '<p><strong>Youtube API Integration:</strong></p>\r\n<ul>\r\n<li>API Integration with youtube channel</li>\r\n<li>All video from youtube channel will be shown on the website</li>\r\n<li>When a new video or videos uploaded on youtube it will automatically show it on the website</li>\r\n<li>Comments on vidoes from website will be integrated with facebook page.\r\n<ul>\r\n<li>when a visitor comments on the video on website it will be shown on the facebook.</li>\r\n</ul>\r\n</li>\r\n</ul>', '4500.00', NULL, NULL, NULL, 1, NULL, 'other'),
(40, 'E-Mail Marketing Campaign', '<p>- Customized email Brocheur/ Email Message will be designed</p>\r\n<p>- Message will be sent to more tha 100000 verified email address</p>\r\n<p>- Complete reporting of campaign will be given to customer</p>\r\n<p>- One Shot email campaign</p>', '2000.00', NULL, NULL, NULL, 3, NULL, 'other'),
(41, 'Facebook E-Commerce Tab (E-Commerce Addon)', '<p><strong>Facebook Integration Features</strong></p>\r\n<ul>\r\n<li>Facebook Application integrated with main Website</li>\r\n<li>Facebook Login Integration</li>\r\n<li>User can buy products in facebook</li>\r\n<li>User can see their account details,order details in facebook</li>\r\n<li>Login with facebook in your main site as well as in facebook application</li>\r\n<li>Publish to your wall</li>\r\n<li>Facebook Like</li>\r\n<li>Facebook Comment</li>\r\n<li>Invite friends to your store</li>\r\n<li>Enjoy exciting features of OpenCart/JooCart in Facebook</li>\r\n<li>vQmod and no vQmod both version are included</li>\r\n<li>Options for left/right column</li>\r\n<li>Multistored*</li>\r\n<li>Options for changing color of template</li>\r\n<li>Options for automatic registration</li>\r\n</ul>', '6000.00', NULL, NULL, NULL, 1, NULL, 'other'),
(42, 'Social Media Startup - 1', '<p><strong>Facebook, Google Plus &amp; Pinterest</strong></p>\r\n<p>A Perfect Package for Starters includes:</p>\r\n<p><strong>Facebook:</strong></p>\r\n<ul>\r\n<li>Facebook Page Creation</li>\r\n<li>Brand Optimized Profile Picture and Header</li>\r\n<li>Integration with Blog if any</li>\r\n<li>First 100 Fans</li>\r\n<li>Branded URL <span>e.g. facekook.com/yourbrand</span></li>\r\n<li>First 5 Posts</li>\r\n</ul>\r\n<p><strong>Google Plus:</strong></p>\r\n<ul>\r\n<li>Google Plus Page Creation</li>\r\n<li>Brand Optimized Profile Picture and header</li>\r\n<li>First 5 Posts</li>\r\n<li>25 Google Plus</li>\r\n</ul>\r\n<p><strong>Pinterest:</strong></p>\r\n<ul>\r\n<li>Profile Creation</li>\r\n<li>3 Boards creation</li>\r\n<li>Following 100 Targeted users</li>\r\n</ul>\r\n<p><strong>Note</strong>: All of this activity is done by a Marketing specialist after research related to client business and activities.</p>\r\n<p><strong>Delivery Time:</strong> 15 Days, Facebook Fans are delivered in 30 Days</p>', '3800.00', NULL, NULL, NULL, 1, NULL, 'other'),
(43, 'Business Cards', '<ul>\r\n<li>1000-Business Cards</li>\r\n<li>350-g Art Card Glossy / Matt</li>\r\n<li>4/4 color printing&nbsp;</li>\r\n<li>size: 9 x 5.5 cm&nbsp;</li>\r\n<li>special: Glossy / Matt Lamination ( both side )</li>\r\n</ul>', '895.00', NULL, NULL, NULL, 1, NULL, 'other'),
(44, 'Leaflet', '<ul>\r\n<li>1000-Leaflet</li>\r\n<li>Size: A4</li>\r\n<li>4/4 color printing</li>\r\n<li>170-g Art Paper Glossy / Matt</li>\r\n</ul>', '1250.00', NULL, NULL, NULL, 1, NULL, 'other'),
(45, 'Letter Head', '<ul>\r\n<li>1000-Letter Head</li>\r\n<li>conqueror paper</li>\r\n<li>4-color printing</li>\r\n<li>size: A4 approx.</li>\r\n</ul>', '895.00', NULL, NULL, NULL, 1, NULL, 'other'),
(46, 'Letter Head', '<ul>\r\n<li>1000-Letter Head</li>\r\n<li>conqueror paper</li>\r\n<li>4-color printing</li>\r\n<li>size: A4 approx.</li>\r\n</ul>', '895.00', NULL, NULL, NULL, 1, NULL, 'other'),
(47, 'Envelops', '<ul>\r\n<li>1000-Envelops (DL) &nbsp;AED: 895</li>\r\n<li>1000-Envelops ( A4 ) AED: 1195</li>\r\n<li>Ready Made&nbsp;</li>\r\n<li>4-color printing</li>\r\n<li>edge to edge printing is not possible</li>\r\n</ul>', '0.00', NULL, NULL, NULL, 1, NULL, 'other'),
(48, 'Cash Receipt Vouchers', '<ul>\r\n<li>1000-Sets Cash Receipts&nbsp;</li>\r\n<li>1+3 ( 50-sets in one Book )&nbsp;</li>\r\n<li>required sr. numbers</li>\r\n<li>size: A4&nbsp;AED: 950</li>\r\n<li>size: A5&nbsp;AED: 750</li>\r\n<li>single color printing</li>\r\n</ul>', '0.00', NULL, NULL, NULL, 1, NULL, 'other'),
(49, 'Brochure', '<ul>\r\n<li>1000-Brochure AED: 11,200</li>\r\n<li>Size: A4 , 16 pages ( 8-sheets )</li>\r\n<li>Cover: 350-Art Card Glossy / Matt 4-pages ( 2-sheets )</li>\r\n<li>Inner: 170-g Art Paper Glossy / Matt 12-pages ( 6-sheets )</li>\r\n<li>4/4 Color Priting</li>\r\n<li>Saddle / Perfect Binding</li>\r\n<li>Special: Glossy / Matt Lamination on cover ( single side )</li>\r\n</ul>', '0.00', NULL, NULL, NULL, 1, NULL, 'other'),
(50, 'Google Adwords', '<p>Google Adwords Campaign Management</p>', '0.00', NULL, NULL, NULL, 1, NULL, 'other'),
(51, 'PDF Brochure', '<p><strong>Profile Design</strong></p>\r\n<p>- Graphically Rich &amp; Corporate Style Profile Deisgn<br />- PDF Conversion</p>', '200.00', NULL, NULL, NULL, 7, NULL, 'other'),
(52, 'Custom Services', '<p class=\"usertext\">Internet Services</p>', '497.00', NULL, NULL, NULL, 5, NULL, 'other'),
(53, '5 Email Accounts', '<h2>5 Email Accounts</h2>\r\n<p>Our feature-packed Email Hosting packages are a perfect match for every need.</p>\r\n<table class=\"table-data\" style=\"width: 418px; height: 330px;\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr><th style=\"text-align: left;\" colspan=\"2\">Email Access</th></tr>\r\n<tr>\r\n<td>SMTP/POP3/IMAP Access</td>\r\n<td class=\"alter-bg-2\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>Web-Based Email Access</td>\r\n<td class=\"alter-bg-2\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>Blackberry Enabled</td>\r\n<td class=\"alter-bg-2\">&nbsp;</td>\r\n</tr>\r\n<tr><th style=\"text-align: left;\" colspan=\"2\">Email Utilities and Tools</th></tr>\r\n<tr>\r\n<td>Online Address Book</td>\r\n<td class=\"alter-bg-2\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>Mailing Lists</td>\r\n<td class=\"alter-bg-2\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>Vacation Auto-responders</td>\r\n<td class=\"alter-bg-2\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>Folder Management</td>\r\n<td class=\"alter-bg-2\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>Sorting and Searching</td>\r\n<td class=\"alter-bg-2\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>Full HTML Email Support</td>\r\n<td class=\"alter-bg-2\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>Easy-to-use Control Panel</td>\r\n<td class=\"alter-bg-2\">&nbsp;</td>\r\n</tr>\r\n<tr><th style=\"text-align: left;\" colspan=\"2\">Security and Other Features</th></tr>\r\n<tr>\r\n<td>E-mail Forwards</td>\r\n<td class=\"alter-bg-2\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>E-mail Aliases</td>\r\n<td class=\"alter-bg-2\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>Virus Protection</td>\r\n<td class=\"alter-bg-2\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>Spam Protection</td>\r\n<td class=\"alter-bg-2\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>Total DNS Control</td>\r\n<td class=\"alter-bg-2\">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>', '500.00', NULL, NULL, NULL, 4, NULL, 'other'),
(54, 'Social Media Maintenance', '<p>Min. of 4 Daily Updates/5 days week: Feeds Social Networking Sites</p>\r\n<p><strong>Facebook Profile Maintenance</strong></p>\r\n<ul>\r\n<li>Join Groups and Send Friend Requests to Members</li>\r\n<li>Post comments to Friends Status Updates</li>\r\n<li>Confirm Friend Requests and post Thank You message to their wall</li>\r\n<li>Post Events, Video, Photos, Notes</li>\r\n<li>Invite Friends to become Fans</li>\r\n</ul>\r\n<p><strong>Google Plus Profile Maintenance</strong></p>\r\n<ul>\r\n<li>Join Groups and Send Friend Requests to Members</li>\r\n<li>Post comments to Friends Status Updates</li>\r\n<li>Confirm Friend Requests and post Thank You message to their wall</li>\r\n<li>Post Events, Video, Photos, Notes</li>\r\n</ul>\r\n<p><strong>Twitter Maintenance</strong></p>\r\n<ul>\r\n<li>Invite 250 Targeted Followers</li>\r\n<li>Live Tweet five days per week: Consist of posting updates, retweeting, responding to direct messages and replies</li>\r\n<li>Implement and manage contests to increase activity</li>\r\n</ul>', '2000.00', NULL, NULL, NULL, 3, NULL, 'other'),
(55, 'Email Campaign', '<p><strong>Email Campaign</strong></p>\r\n<ul>\r\n<li>Email Brochure: Designing and Conversion to HTML</li>\r\n<li>Testing of Email Brochure in 7 Different Email Clients to make sure it will be properly viewable</li>\r\n<li>Online Version of Email Brochure</li>\r\n<li>Testing of Email Campaign for SPAM Words</li>\r\n<li>100% Tested 200,000 + &nbsp;Email Database of UAE Companies</li>\r\n<li>Whitelisted Reputed SMTP Server</li>\r\n<li>30 Days Emails Opening and Click Through Reports</li>\r\n</ul>', '2500.00', NULL, NULL, NULL, 3, NULL, 'other'),
(56, 'Google Analytic Integration', '<p><strong>Google Analytic Integration</strong></p>\r\n<ul>\r\n<li>Real Time Reporting - Measure activities on your website</li>\r\n<li>Analyse Your Vistors, From Where they came, Through Which Source they came, How much time they spend</li>\r\n<li>Easy to use Dashboard</li>\r\n</ul>', '0.00', NULL, NULL, NULL, 3, NULL, 'other'),
(57, 'Responsive Web Design', '<ul>\r\n<li>Optimised Display on All Phones</li>\r\n<li>Optimised Display on Tablet Devices</li>\r\n<li>Optimised User Experience</li>\r\n<li>Optimized Loading Speed for Smaller Devices</li>\r\n<li>Search Engine Optimised for Smaller Devices</li>\r\n<li>Manage the Same Code, Files and Administration for all Devices</li>\r\n</ul>', '0.00', NULL, NULL, NULL, 1, NULL, 'other'),
(58, 'Catalogue Design', '<p>- 200 Dhs Per Internal Page</p>\r\n<p>- 600 Dhs for Title &amp; Back Page</p>', '200.00', NULL, NULL, NULL, 7, NULL, 'other'),
(60, 'Translation service', '<p>English to Arabic&nbsp;</p>', '0.00', NULL, NULL, NULL, 1, NULL, 'other'),
(61, 'Translation service', '<p>English to Arabic&nbsp;</p>', '0.00', NULL, NULL, NULL, 1, NULL, 'other'),
