(65, 'Seach Box Within Website', '', '500.00', NULL, NULL, NULL, 1, NULL, 'other'),
(66, 'Recruitment Web Portal', '<p><strong>General Features:</strong></p>\r\n<ul>\r\n<li>Graphically Rich web Design With Jquery Banners (English)</li>\r\n<li><span style=\"font-size: 10pt;\">Powerful CMS.</span></li>\r\n<li><span style=\"font-size: 10pt;\">Add/Edit/Delete Unlimited Pages and add Unlimited Pictures</span></li>\r\n<li><span style=\"font-size: 10pt;\">Complete Structure will be developed as per the Sitemap provided</span></li>\r\n<li><span style=\"font-size: 10pt;\">Video Enabled</span></li>\r\n<li><span style=\"font-size: 10pt;\">Specialized Media Pages with News Updating Facility</span></li>\r\n<li><span style=\"font-size: 10pt;\">Dynamic Picture Gallery</span></li>\r\n<li><span style=\"font-size: 10pt;\">Social Media Sharing (Facebook Share, Like, Twitter, etc)</span></li>\r\n<li><span style=\"font-size: 10pt;\">SEO Friendly</span></li>\r\n<li><span style=\"font-size: 10pt;\">High class XHTM Standard based development allows future e</span><span style=\"font-size: 10pt;\">xtendibility of features easy</span></li>\r\n<li><span style=\"font-size: 10pt;\">Cross-Browser compatibility</span></li>\r\n<li><span style=\"font-size: 10pt;\">Cross-Device Compatibility</span></li>\r\n<li><span style=\"font-size: 10pt;\">CMS support Adding New features fast and easy</span></li>\r\n</ul>\r\n<p><strong>Specialized Features:</strong></p>\r\n<ul>\r\n<li>Employer Can Register, Maintain his Account and Post Jobs</li>\r\n<li>Featured Employers Section</li>\r\n<li><span>Candidate can Register and Upload his CV</span></li>\r\n<li><span>Candidate can search Jobs based on Various Crieteria using Powerful Search Module</span></li>\r\n<li>Candidate can apply for Job</li>\r\n</ul>', '12000.00', NULL, NULL, NULL, 1, NULL, 'other'),
(67, 'Additional Customize Work', '', '0.00', NULL, NULL, NULL, 1, NULL, 'other'),
(68, 'Retrieving Data ', '', '3500.00', NULL, NULL, NULL, 1, NULL, 'other'),
(69, 'Real Estate Web Design', '<ol>\r\n<li><strong>Jquery Banner</strong></li>\r\n<li><strong>Home</strong></li>\r\n<li><strong>About Us</strong><ol>\r\n<li>Brief Intro</li>\r\n<li>Mission</li>\r\n<li>Vision</li>\r\n<li>Managing Director Massage</li>\r\n<li>The Team</li>\r\n</ol></li>\r\n<li><strong>About Dubai</strong></li>\r\n<li><strong>Property Search</strong><ol>\r\n<li>I want to ( Buy &amp; Rent )</li>\r\n<li>By Emirates</li>\r\n<li>By Requirements OR By Property<ol>\r\n<li>Commercial Property</li>\r\n<li>Residential Apartments</li>\r\n<li>Villas</li>\r\n<li>land</li>\r\n<li>Building</li>\r\n<li>Ware House</li>\r\n<li>Labor Camp</li>\r\n<li>Hotels</li>\r\n<li>Plots</li>\r\n</ol></li>\r\n<li>By Projects</li>\r\n<li>By Price</li>\r\n<li>By Location</li>\r\n<li>By&nbsp; All Bedroom and Studio</li>\r\n</ol></li>\r\n<li><strong>Buy Property</strong><ol>\r\n<li>Property Details</li>\r\n<li>Property Location map (Image)</li>\r\n<li>Property Floor Plan (Image)</li>\r\n<li>Payment Plan (Description)</li>\r\n<li>Buy Property Form</li>\r\n</ol></li>\r\n<li><strong>Sell Property OR Property Listing</strong></li>\r\n<li><strong>Rent&nbsp; / Lease Property</strong><ol>\r\n<li>Property Details</li>\r\n<li>Property Location map (Image)</li>\r\n<li>Property Floor Plan (Image)</li>\r\n<li>Property Pictures</li>\r\n<li>Rent Property Form</li>\r\n</ol></li>\r\n<li><strong>Property News.</strong></li>\r\n<li><strong>Featured Property</strong><ol>\r\n<li>Hot Property</li>\r\n<li>Coming Soon Property</li>\r\n<li>Property of the Month</li>\r\n</ol></li>\r\n<li><strong>Enquiry&nbsp; Form</strong></li>\r\n<li><strong>Contact Us (With Google Location Map)</strong></li>\r\n</ol>', '7500.00', NULL, NULL, NULL, 1, NULL, 'other'),
