INSERT INTO `tblitems_in` (`id`, `rel_id`, `rel_type`, `description`, `long_description`, `qty`, `rate`, `unit`, `item_order`, `start_date`, `end_date`, `is_renew_able`, `renewal_cancel`, `renewal_cancel_reason`, `renewal_user_id`, `service`, `frequency`, `discount`, `discount_once`, `renewal_invoice_created`, `first_reminder_sent`, `second_reminder_sent`, `third_reminder_sent`, `item_type`) VALUES
(1014, 620, 'invoice', 'Website Maintenance', '<p><strong>Website Maintenance Services (Additional Hours)</strong></p>\r\n<p><strong>Task List</strong></p>\r\n<p>&raquo; To add &ldquo;New Year&rsquo;s Greeting&rdquo; message on Home Page</p>\r\n<p>&raquo; To add &ldquo;Independence Day Celebration Invitation&rdquo; on &ldquo;News &amp; Happenings&rdquo; Page.</p>\r\n<p>&raquo; To remove last article from Home Page</p>\r\n<p>&raquo; To add images in &ldquo;Events Gallery&rdquo;.</p>\r\n<p><strong><br /></strong><strong style=\"font-size: 10pt;\">Data Provided.</strong></p>\r\n<p>Total of 207 images were provided.</p>\r\n<p><strong>Task Duration</strong></p>\r\n<p><strong>&nbsp;Day 1 ( 5 hours)</strong></p>\r\n<p>Optimized first 96 images, with re-scaling according to web specs.</p>\r\n<p>Uploaded images to respective directories.</p>\r\n<p>Added 2 images on home page and news and happenings page.</p>\r\n<p><strong style=\"font-size: 10pt;\">Day 2 (5 hours)</strong></p>\r\n<p>Created article pages for first 7 directory folders.</p>\r\n<p>Linked 3 articles to gallery pages.</p>\r\n<p><strong>Day 3 ( 3 hours)</strong></p>\r\n<p>Optimized remaining 111 images for web with re-scaling.</p>\r\n<p><strong>Day 4 ( 3hours)</strong></p>\r\n<p>Created remaining 10 folders in image gallery and uploaded images</p>\r\n<p>Created 10 articles for each uploaded directory</p>\r\n<p><strong>Day 5 (3 hours)</strong></p>\r\n<p>Created 18 boxes in gallery page and linked with each articles and directory folders.</p>\r\n<p><strong>Total Hours: 19 Hours<br />Allowed Hours in a month: 3<br />Additional Hours: 16</strong></p>', '16.00', '120.00', NULL, NULL, '0000-00-00', '0000-00-00', '', 0, NULL, NULL, 70, 'Monthly', '0', 'N', '0', '0', '0', '0', 'other'),
(1015, 621, 'invoice', 'E-Commerce Web Development', '<p><strong>- Professionally Designed Store Front with Jquery Banner</strong><strong><br /> <strong>- Mobile Friendly</strong></strong></p>\r\n<p><span style=\"text-decoration: underline;\"><em style=\"font-size: 10pt;\">Product Catalogue:</em></span></p>\r\n<ul>\r\n<li>Unlimited Products, Unlimited Categories/Sub Categories Structure</li>\r\n<li>Unlimited Pictures Per Product, Zooming, etc</li>\r\n</ul>\r\n<p><span style=\"text-decoration: underline;\"><em>Shopping Cart:</em></span></p>\r\n<ul>\r\n<li>Simple and Easy to Use Order Process</li>\r\n<li>Customer Account or Checkout as guest</li>\r\n</ul>\r\n<p><span style=\"text-decoration: underline;\"><em>Powerful Shipping Handling:</em></span></p>\r\n<ul>\r\n<li><span style=\"font-size: 10pt;\">Automatic Shipping Calculation by Price or Weight, Zone</span></li>\r\n<li><span style=\"font-size: 10pt;\">Unlimited Carriers and Destinations</span></li>\r\n</ul>\r\n<p><span style=\"text-decoration: underline;\"><em>Payment Gateway:</em></span></p>\r\n<ul>\r\n<li><span style=\"font-size: 10pt;\">Integration with Paypal, 2CO, Cash On Delivery</span></li>\r\n<li>Additional Payment Gateways*</li>\r\n</ul>\r\n<p><span style=\"text-decoration: underline;\"><em>Order Management & Customer Handling</em></span></p>\r\n<ul>\r\n<li>Complete Customer Account</li>\r\n<li>Email Notifications to Customers for Change in Order Status</li>\r\n</ul>\r\n<p><span style=\"text-decoration: underline;\"><em>Additional Features:</em></span></p>\r\n<ul>\r\n<li>New Designers can Register and showcase their work</li>\r\n<li>Users can select Frames, and Pictures will be shown in Frames on Run Time</li>\r\n<li>Users can follow their Favorite Artists, and Whenever a New Picture will be added by Artist, User will get a notification Email</li>\r\n</ul>\r\n<p><span style=\"font-size: 10pt;\">*Extra Cost Items</span></p>', '1.00', '26000.00', NULL, NULL, '0000-00-00', '0000-00-00', '', 0, NULL, NULL, 28,