(1790, 1124, 'invoice', 'Web Designing (CMS)', '<ul>\r\n<li>Graphically Rich web Design With Jquery Banners (English)</li>\r\n<li>Powerful CMS.</li>\r\n<li>Add/Edit/Delete Unlimited Pages and add Unlimited Pictures</li>\r\n<li>Complete Structure will be developed as per the Sitemap provided</li>\r\n<li>Video Enabled </li>\r\n<li>Specialized Media Pages with News Updating Facility</li>\r\n<li>Dynamic Picture Gallery </li>\r\n<li>Social Media Sharing (Facebook Share, Like, Twitter, etc)</li>\r\n<li>SEO Friendly</li>\r\n<li>High class XHTM Standard based development allows future extendibility of features easy</li>\r\n<li>Cross-Browser compatibility</li>\r\n<li>Cross-Device Compatibility</li>\r\n<li>CMS support Adding New features fast and easy</li>\r\n</ul>', '1.00', '8500.00', NULL, NULL, '0000-00-00', '0000-00-00', '', 0, NULL, NULL, 23, 'Once', '0', 'N', '0', '0', '0', '0', 'other'),
(1791, 1125, 'invoice', 'Web Designing (CMS)', '<ul>\r\n<li>Graphically Rich web Design With Jquery Banners (English)</li>\r\n<li>Powerful CMS.</li>\r\n<li>Add/Edit/Delete Unlimited Pages and add Unlimited Pictures</li>\r\n<li>Complete Structure will be developed as per the Sitemap provided</li>\r\n<li>Video Enabled </li>\r\n<li>Specialized Media Pages with News Updating Facility</li>\r\n<li>Dynamic Picture Gallery </li>\r\n<li>Social Media Sharing (Facebook Share, Like, Twitter, etc)</li>\r\n<li>SEO Friendly</li>\r\n<li>High class XHTM Standard based development allows future extendibility of features easy</li>\r\n<li>Cross-Browser compatibility</li>\r\n<li>Cross-Device Compatibility</li>\r\n<li>CMS support Adding New features fast and easy</li>\r\n</ul>', '1.00', '13000.00', NULL, NULL, '0000-00-00', '0000-00-00', '', 0, NULL, NULL, 23, 'Monthly', '0', 'N', '0', '0', '0', '0', 'other'),
(1792, 1126, 'invoice', 'Custom Web Development Service', '<p><strong>Maintenance Management System</strong></p>\r\n<p>- Admin can create Tenants, Properties, Units, Add Employees, and Maintenance Types</p>\r\n<p>- Admin can create and see various type of Maintenance Requests</p>\r\n<p>- Tenats can login, update their profile, and make various maintenance requests</p>\r\n<p>- Admins and Company employee can view requests and Update work done against each request</p>\r\n<p>- Reports to analyse Employee Perfomance, History of Various Units, and Tenats Requests</p>\r\n<p>- Operatable form Mobiles and Desktops</p>', '1.00', '30000.00', NULL, NULL, '0000-00-00', '0000-00-00', '', 0, NULL, NULL, 11, 'Once', '0', 'N', '0', '0', '0', '0', 'other'),
