(3250, 1853, 'invoice', '5 Email Accounts', '<h2>5 Email Accounts</h2> <br /><br />\r\n<p>Our feature-packed Email Hosting packages are a perfect match for every need.</p> <br /><br />\r\n<table class=\"table-data\" style=\"width: 418px; height: 330px;\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\"> <br /><br />\r\n<tbody> <br /><br />\r\n<tr><th style=\"text-align: left;\" colspan=\"2\">Email Access</th></tr> <br /><br />\r\n<tr> <br /><br />\r\n<td>SMTP/POP3/IMAP Access</td> <br /><br />\r\n<td class=\"alter-bg-2\"> </td> <br /><br />\r\n</tr> <br /><br />\r\n<tr> <br /><br />\r\n<td>Web-Based Email Access</td> <br /><br />\r\n<td class=\"alter-bg-2\"> </td> <br /><br />\r\n</tr> <br /><br />\r\n<tr> <br /><br />\r\n<td>Blackberry Enabled</td> <br /><br />\r\n<td class=\"alter-bg-2\"> </td> <br /><br />\r\n</tr> <br /><br />\r\n<tr><th style=\"text-align: left;\" colspan=\"2\">Email Utilities and Tools</th></tr> <br /><br />\r\n<tr> <br /><br />\r\n<td>Online Address Book</td> <br /><br />\r\n<td class=\"alter-bg-2\"> </td> <br /><br />\r\n</tr> <br /><br />\r\n<tr> <br /><br />\r\n<td>Mailing Lists</td> <br /><br />\r\n<td class=\"alter-bg-2\"> </td> <br /><br />\r\n</tr> <br /><br />\r\n<tr> <br /><br />\r\n<td>Vacation Auto-responders</td> <br /><br />\r\n<td class=\"alter-bg-2\"> </td> <br /><br />\r\n</tr> <br /><br />\r\n<tr> <br /><br />\r\n<td>Folder Management</td> <br /><br />\r\n<td class=\"alter-bg-2\"> </td> <br /><br />\r\n</tr> <br /><br />\r\n<tr> <br /><br />\r\n<td>Sorting and Searching</td> <br /><br />\r\n<td class=\"alter-bg-2\"> </td> <br /><br />\r\n</tr> <br /><br />\r\n<tr> <br /><br />\r\n<td>Full HTML Email Support</td> <br /><br />\r\n<td class=\"alter-bg-2\"> </td> <br /><br />\r\n</tr> <br /><br />\r\n<tr> <br /><br />\r\n<td>Easy-to-use Control Panel</td> <br /><br />\r\n<td class=\"alter-bg-2\"> </td> <br /><br />\r\n</tr> <br /><br />\r\n<tr><th style=\"text-align: left;\" colspan=\"2\">Security and Other Features</th></tr> <br /><br />\r\n<tr> <br /><br />\r\n<td>E-mail Forwards</td> <br /><br />\r\n<td class=\"alter-bg-2\"> </td> <br /><br />\r\n</tr> <br /><br />\r\n<tr> <br /><br />\r\n<td>E-mail Aliases</td> <br /><br />\r\n<td class=\"alter-bg-2\"> </td> <br /><br />\r\n</tr> <br /><br />\r\n<tr> <br /><br />\r\n<td>Virus Protection</td> <br /><br />\r\n<td class=\"alter-bg-2\"> </td> <br /><br />\r\n</tr> <br /><br />\r\n<tr> <br /><br />\r\n<td>Spam Protection</td> <br /><br />\r\n<td class=\"alter-bg-2\"> </td> <br /><br />\r\n</tr> <br /><br />\r\n<tr> <br /><br />\r\n<td>Total DNS Control</td> <br /><br />\r\n<td class=\"alter-bg-2\"> </td> <br /><br />\r\n</tr> <br /><br />\r\n</tbody> <br /><br />\r\n</table>', '12.00', '60.00', '', 2, '0000-00-00', '0000-00-00', '', 0, NULL, NULL, 0, '', '0', 'Y', '0', '0', '0', '0', 'other'),
(3251, 148, 'proposal', 'Web Hosting 5000', '<ul><br />\r\n<li>Web Hosting 5000 MB</li><br />\r\n<li>Bandwidth: 50,000 MB Per month</li><br />\r\n<li>Languages Support: PHP, Java</li><br />\r\n<li>Database: MYSQL (5 Databases)</li><br />\r\n<li>Number of Emails: 50</li><br />\r\n</ul><br />\r\n<br />\r\n<span>Website Speed Optimization</span><br />\r\n<ul><br />\r\n<li>Complete Optimization to make Google Speed Score to 75+</li><br />\r\n<li>Minifying and Optimization of Scripts</li><br />\r\n<li>Images Optimization</li><br />\r\n<li>Cache Handling</li><br />\r\n<li>Bi-Monthly Tests</li><br />\r\n<li>*In case of Slow Hosting, Hosting may have to be changed</li><br />\r\n</ul><br />\r\n<span>Secure Socket Layer (SSL)</span><br />\r\n<ul><br />\r\n<li>Implementation and Maintenance</li><br />\r\n</ul><br />\r\n<span>Website Maintenance Services</span><br />\r\n<ul><br />\r\n<li>Backup Frequency: Monthly (Offline)</li><br />\r\n<li>CMS Updates (As Available) : Monthly</li><br />\r\n<li>Backup is Maintained <g class=\"gr_ gr_44 gr-alert gr_gramm gr_inline_cards gr_run_anim Punctuation only-del replaceWithoutSep\" id=\"44\" data-gr-id=\"44\"><g class=\"gr_ gr_42 gr-alert gr_spell gr_inline_cards gr_disable_anim_appear ContextualSpelling ins-del multiReplace\" id=\"42\" data-gr-id=\"42\">upto</g>:</g>     3 Months</li><br />\r\n<li>Plugins Updates (As Available)</li><br />\r\n<li>Theme Updates whenever necessary with <g class=\"gr_ gr_46 gr-alert gr_gramm gr_inline_cards gr_run_anim Grammar only-ins doubleReplace replaceWithoutSep\" id=\"46\" data-gr-id=\"46\">update</g> in CMS</li><br />\r\n</ul><br />\r\n<br />\r\n<span>Regular Turn Around Time:    48 HoursEmergency Turn Around Time:   12 Hours - Additional Hours Of Design & Maintenance: 110 </span>', '12.00', '300.00', 'Months', 1, '0000-00-00', '0000-00-00', '0', 0, NULL, NULL, 0, '', '0', 'Y', '0', '0', '0', '0', 'other'),
