(462, 'Make Variants Group ', '', 2, '2018-05-07 11:37:06', '2018-05-07', NULL, '0000-00-00 00:00:00', 27, 0, 4, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, 1, 0, 0, '0.00', 0, 0, 0, 0, 0, 'work', '', 30, 'minute', '1', 0, '0', 'mannual'),
(463, 'POS Variants', '<p>-&gt;Update variants as discussed</p>\r\n<p>-&gt; make new view and design&nbsp;</p>\r\n<p>-&gt;make combinations nth level</p>\r\n<p>-&gt;variants addition</p>\r\n<p>-&gt;variants update</p>\r\n<p>-&gt; validation for remove and update for already used&nbsp; combinations</p>\r\n<p>(disable values)</p>\r\n<p>-&gt; update controllers and models for back-end insertion and updates</p>\r\n<p>-&gt; add table \"Products_combination\" for manage combinations in database as well for update purpose.</p>\r\n<p></p>\r\n<p>&nbsp;</p>', 3, '2018-05-10 06:42:53', '2018-05-09', NULL, '2018-05-10 06:43:00', 32, 0, 5, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, 1, 0, 0, '0.00', 0, 0, 0, 0, 0, '', '', 30, 'minute', '1', 0, '0', 'mannual'),
(464, 'Download form from request form', '<ul>\r\n<li>The user can download a form from request form in their logins</li>\r\n<li>in backend give the option to upload document and frontend user can download it</li>\r\n</ul>\r\n<p></p>', 2, '2018-05-10 09:57:29', '2018-05-10', NULL, '2018-05-14 11:00:58', 22, 0, 5, NULL, 0, 0, NULL, 0, NULL, 73, 'project', 0, 1, 0, 0, '0.00', 0, 0, 0, 1, 0, 'work', '', 30, 'minute', '1', 0, '0', 'mannual'),
(465, 'Tax Calculation with Variant price', '&gt; On the adminPanel of Enso Calculate the correct Tax calculation With variant price.', 4, '2018-05-11 19:23:52', '2018-05-11', NULL, '2018-05-11 19:24:12', 27, 0, 5, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, 1, 0, 0, '0.00', 0, 0, 0, 1, 0, 'work', '', 30, 'minute', '1', 0, '0', 'mannual'),
(466, 'POS inclusive tax option for only products', 'On printing label(without variant prices)', 2, '2018-05-11 19:25:34', '2018-05-10', NULL, '2018-05-11 19:25:37', 32, 0, 5, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, 1, 0, 0, '0.00', 0, 0, 0, 0, 0, '', '', 0, 'minute', '1', 0, '0', 'mannual'),
(467, 'Move Customer variant group', '<p>&gt; Move Customer group to Sales Tab&nbsp;</p>\r\n<p>In this move all the functions of controller, models and Views place in the sales.</p>', 2, '2018-05-11 19:26:37', '2018-05-11', NULL, '2018-05-11 19:26:39', 27, 0, 5, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, 1, 0, 0, '0.00', 0, 0, 0, 0, 0, 'work', '', 0, 'minute', '1', 0, '0', 'mannual'),
(468, 'Variant Of POS Webiste integration', '<p>-&gt;Jquery conflict solved for check witch slider (icheck plugin)</p>\r\n<p>-&gt; Update website status on add product</p>\r\n<p>-&gt; Update website status on edit for already saved</p>\r\n<p>-&gt; new combination and disabled combination is in progress&nbsp;</p>', 2, '2018-05-11 19:29:22', '2018-05-11', NULL, '2018-05-17 23:25:25', 32, 0, 5, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, 1, 0, 0, '0.00', 0, 0, 0, 0, 0, '', '', 0, 'minute', '1', 0, '0', 'mannual'),
(469, 'Barcode Font size', '<p>&gt;Barcode Font size and barcode Image make them little bigger as per the client requirement.&nbsp;</p>\r\n<p>The size is 2.5x1.5</p>', 2, '2018-05-11 19:29:50', '2018-05-11', NULL, '2018-05-11 19:29:52', 27, 0, 5, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, 1, 0, 0, '0.00', 0, 0, 0, 0, 0, 'work', '', 0, 'minute', '1', 0, '0', 'mannual'),
(470, 'Add VISA number & Expiry date in tenant form', '', 2, '2018-05-14 11:21:44', '2018-05-14', NULL, '2018-05-15 15:54:47', 22, 0, 5, NULL, 0, 0, NULL, 0, NULL, 73, 'project', 0, 1, 0, 0, '0.00', 0, 0, 0, 1, 0, 'work', '', 30, 'minute', '1', 0, '0', 'mannual'),
(471, 'Left side bar options replacement >Enso- Admin', '<p>In the Enso Admin panel left side bar some elements replacement to the sale section.</p>\r\n<p>Price Group, Discount Group, List of customers shifted to Sales section.</p>', 2, '2018-05-14 16:07:04', '2018-05-14', NULL, '2018-05-14 16:07:18', 27, 0, 5, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, 1, 0, 0, '0.00', 0, 0, 0, 0, 0, 'work', '', 0, 'minute', '1', 0, '0', 'mannual'),
(472, 'Study about Price Group and Discount Group', '<p><strong>Price Group:</strong></p>\r\n<p>In the price group admin can assign specific group to the customers.</p>\r\n<p>In the price group all products listed down from where can also update the price of product. so this price will be implement to the group.</p>\r\n<p></p>\r\n<p><strong>Discount Group:</strong></p>\r\n<p>When assign the discount group to the specific user then this price will be implemented to customer.&nbsp;</p>\r\n<p></p>\r\n<p>*Note: If both are assign to the customer then both are implemented to the item.</p>', 2, '2018-05-14 16:07:38', '2018-05-14', NULL, '2018-05-14 16:12:04', 27, 0, 5, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, 1, 0, 0, '0.00', 0, 0, 0, 0, 0, 'work', '', 0, 'minute', '1', 0, '0', 'mannual'),
(473, 'Study about Add user in customers', 'Actually it behaves like a company. and in the company admin can add multiple user in it. So on the front both users can see the same orders and products details because these customers part of the same company.&nbsp;', 2, '2018-05-14 16:14:43', '2018-05-14', NULL, '2018-05-14 16:14:47', 27, 0, 5, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, 1, 0, 0, '0.00', 0, 0, 0, 0, 0, 'work', '', 0, 'minute', '1', 0, '0', 'mannual'),
(474, 'Tax calculation on POS', '<p>On the POS when we calculate the tax then tax calculation of each item is not done by default.&nbsp;</p>\r\n<p>Some products have 5% tax some have 10% tax some products have inclusive and some have exculusive&nbsp;</p>\r\n<p>All the cases handle in it. and tax price calculation shows in the tax section of the added products in POS</p>', 4, '2018-05-14 16:17:55', '2018-05-14', NULL, '2018-05-14 16:18:03', 27, 0, 5, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, 1, 0, 0, '0.00', 0, 0, 0, 0, 0, 'work', '', 0, 'minute', '1', 0, '0', 'mannual'),
(475, 'Price Rounding in POS', '<p>&gt;Enso admin panel:</p>\r\n<p>By default Price rounding not effected in the POS items.&nbsp;</p>\r\n<p>Its fixed</p>', 4, '2018-05-14 16:19:10', '2018-05-14', NULL, '2018-05-14 16:19:14', 27, 0, 5, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, 1, 0, 0, '0.00', 0, 0, 0, 0, 0, 'work', '', 0, 'minute', '1', 0, '0', 'mannual'),
(476, 'Tax calculation on Invoice', '<p>Enso Admin panel:</p>\r\n<p>POS invoice not calculating the tax in it. Its fixed.Now each item have price in own row and tax separately calculated.</p>', 4, '2018-05-14 16:21:32', '2018-05-14', NULL, '2018-05-14 16:21:35', 27, 0, 5, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, 0, 1, 0, 0, '0.00', 0, 0, 0, 0, 0, 'work', '', 0, 'minute', '1', 0, '0', 'mannual');
